// PR c++/117937
// { dg-do compile { target c++26 } }

void operate_one(const int) {}

template<typename ...T>
void operate_multi(T... args)
{
    [&]<int idx>()
    {
       ::operate_one(args...[idx]);
    }.template operator()<0>();
}

int main()
{
    ::operate_multi(0);
}

// PR c++/117937
// { dg-do compile { target c++26 } }

using size_t = decltype(sizeof(0));

template<size_t...>
struct seq {};

void g(auto...) {}

void
f (auto... args)
{
  [&]<size_t... i>(seq<i...>) {
      g(args...[i]...);
  }(seq<0>());
}

int
main ()
{
  f(0);
}
